def _looks_like_lru_cache(node) -> bool:
    """Check if the given function node is decorated with lru_cache."""
    if not node.decorators:
        return False
    for decorator in node.decorators.nodes:
        # Check for lru_cache with parentheses (Call node)
        if isinstance(decorator, Call) and _looks_like_functools_member(decorator, "lru_cache"):
            return True

        # Check for lru_cache without parentheses (Name node)
        if isinstance(decorator, Name):
            # Try to infer what this name refers to
            try:
                inferred = next(decorator.infer())
                if inferred.qname() == LRU_CACHE:
                    return True
            except (StopIteration, InferenceError):
                pass

        # Check for lru_cache without parentheses (Attribute node)
        if isinstance(decorator, Attribute) and decorator.attrname == "lru_cache":
            # Check if it's directly from functools
            if isinstance(decorator.expr, Name) and decorator.expr.name == "functools":
                return True

            # Try to infer what module this attribute comes from
            try:
                inferred = next(decorator.expr.infer())
                if hasattr(inferred, "qname") and inferred.qname() == "functools":
                    return True
            except (StopIteration, InferenceError):
                pass

    return False
